public function store(StoreOrderRequest $request, LegacyOrderService $legacy)
{
    if (config('features.new_checkout_flow')) {
        return app(CreateOrderAction::class)->handle($request->validated());
    }

    return $legacy->store($request->validated());
}

class PartnerInvoiceGateway
{
    public function createInvoice(array $payload): PartnerInvoiceResult
    {
        $response = Http::timeout(10)->retry(2, 300)->post(config('services.partner.base_url').'/invoices', [
            'customer_code' => $payload['customer_code'],
            'amount_cents' => $payload['amount'],
        ])->throw();

        return new PartnerInvoiceResult(
            externalId: $response['id'],
            status: $response['status'],
        );
    }
}
